using Godot;
using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using HakutaiKagami.Core.Contracts;
public partial class NewGameRuntime
{
    HFlowContainer militaryBar=null!;OptionButton militaryChoice=null!;Label militaryStatus=null!;NewMilitaryAction[] militaryActions=[];bool drawingMilitary,drawingPersonal;FieldPoint? militaryDrag;
    readonly List<(MeshInstance3D Marker,Label Label)> militaryMarkers=new();
    readonly List<Officer3DCustomActor> militaryModels=new();
    void BuildMilitaryUI(VBoxContainer root){militaryBar=new();root.AddChild(militaryBar);militaryChoice=new(){CustomMinimumSize=new(210,0)};militaryBar.AddChild(militaryChoice);Add(militaryBar,"military-execute","軍務の判断を実行",ExecuteMilitary);Add(militaryBar,"military-frame","部隊全景",()=>{Span=90;nationMode=false;});militaryStatus=new(){AutowrapMode=TextServer.AutowrapMode.WordSmart,SizeFlagsHorizontal=SizeFlags.ExpandFill,CustomMinimumSize=new(320,0)};militaryBar.AddChild(militaryStatus);}
    static string MilitaryActionName(NewMilitaryAction a)=>a switch{NewMilitaryAction.Request=>"主君に軍務を申し出る",NewMilitaryAction.Accept=>"軍務条件に同意",NewMilitaryAction.Pickup=>"現地で兵の指揮を引き受ける",NewMilitaryAction.Load=>"主家兵糧を携行（100人の1日分）",NewMilitaryAction.Unload=>"携行兵糧の残りを全量返納",NewMilitaryAction.Deploy=>"兵とともに野外へ出る",NewMilitaryAction.Form=>"地面に配置線を引く",NewMilitaryAction.Hold=>"その場で保持",NewMilitaryAction.Recall=>"部隊を帰還させる",NewMilitaryAction.Enter=>"本人と兵が拠点に入る",NewMilitaryAction.Report=>"現在の自隊状況を主君へ返報",NewMilitaryAction.Return=>"兵の指揮返還を願い出る",NewMilitaryAction.Inquire=>"軍務許可・返還を照会",NewMilitaryAction.CombatPermit=>"架空演習の交戦許可を願い出る",NewMilitaryAction.CombatStart=>"演習相手と接触する",NewMilitaryAction.CombatEnd=>"演習の接触を終了",NewMilitaryAction.Handoff=>"本隊へ兵糧の運搬を引き継ぐ",NewMilitaryAction.Reclaim=>"本隊から兵糧を受け取る",NewMilitaryAction.Withdraw=>"本人だけ拠点へ退避",NewMilitaryAction.Rejoin=>"最後に確認した本隊の場所へ向かう",NewMilitaryAction.Attach=>"現地で本隊と合流",NewMilitaryAction.Observe=>"目の前の本隊の所在を記録",NewMilitaryAction.RemoteRecall=>"既知の本隊所在地へ撤退伝令",NewMilitaryAction.PersonalHome=>"本人だけ拠点へ戻る",NewMilitaryAction.PersonalMove=>"本人が歩く地点を地面で指定",_=>a.ToString()};
    void RefreshMilitary(){var w=Snapshot();var v=NewGameMilitary.View(w);var list=new List<NewMilitaryAction>();
        if(v.CanRequest)list.Add(NewMilitaryAction.Request);if(v.CanAccept)list.Add(NewMilitaryAction.Accept);if(v.CanPickup&&!v.Returning)list.Add(NewMilitaryAction.Pickup);
        bool local=w.NewMilitary!=null&&w.Locations.Any(l=>l.Actor==w.PlayerControl&&l.Kind==LocationKind.AtSite&&l.Site==w.NewMilitary.Terms.Site);
        if(v.Custody){if(!v.Deployed&&local){if(!v.Returning){if(v.Carry<NewGameMilitary.Capacity)list.Add(NewMilitaryAction.Load);if(v.Carry>0)list.Add(NewMilitaryAction.Deploy);}if(v.Carry>0)list.Add(NewMilitaryAction.Unload);}if(v.Deployed){if(!NewGameMilitary.Detached(w)&&!v.Returning&&v.Carry>0&&!NewGameMilitary.CombatActive(w)&&!NewGameMilitary.RoutActive(w)){list.Add(NewMilitaryAction.Form);list.Add(NewMilitaryAction.Hold);}if(!NewGameMilitary.Detached(w))list.Add(NewMilitaryAction.Recall);if(v.CanEnter)list.Add(NewMilitaryAction.Enter);}if(!NewGameMilitary.Detached(w))list.Add(NewMilitaryAction.Report);}
        if(v.Custody&&!v.Returning&&!w.NewMilitary!.Requests.Any(q=>q.Input.Action==NewMilitaryAction.CombatPermit))list.Add(NewMilitaryAction.CombatPermit);if(NewGameMilitary.CanStartCombat(w))list.Add(NewMilitaryAction.CombatStart);if(NewGameMilitary.CombatActive(w))list.Add(NewMilitaryAction.CombatEnd);
        if((v.Custody||v.CanPickup)&&!v.Returning)list.Add(NewMilitaryAction.Return);if(w.NewMilitary!=null)list.Add(NewMilitaryAction.Inquire);
        foreach(var a in new[]{NewMilitaryAction.Handoff,NewMilitaryAction.Reclaim,NewMilitaryAction.Withdraw,NewMilitaryAction.Rejoin,NewMilitaryAction.Attach,NewMilitaryAction.Observe,NewMilitaryAction.RemoteRecall,NewMilitaryAction.PersonalHome,NewMilitaryAction.PersonalMove})if(NewGameMilitary.WithdrawalAllowed(w,new(new("request:availability"),a)))list.Add(a);
        var actions=list.ToArray();var selected=militaryChoice.Selected>=0&&militaryChoice.Selected<militaryActions.Length?militaryActions[militaryChoice.Selected]:(NewMilitaryAction?)null;
        if(!actions.SequenceEqual(militaryActions)){militaryChoice.Clear();foreach(var a in actions)militaryChoice.AddItem(MilitaryActionName(a));militaryActions=actions;int i=Array.FindIndex(actions,a=>a==selected);if(i>=0)militaryChoice.Select(i);}
        militaryBar.Visible=v.CanRequest||w.NewMilitary!=null;buttons["military-execute"].Disabled=actions.Length==0;militaryStatus.Text=v.Status+(!NewGameMilitary.Detached(w)&&NewGameMilitary.CombatStarted(w)?" / 演習損害："+NewGameMilitary.OwnCombatReport(w,w.ElapsedSeconds).Sum(r=>r.Lost)+"・士気："+string.Join("/",NewGameMilitary.OwnCombatReport(w,w.ElapsedSeconds).Select(r=>r.Morale)):"")+(v.Custody&&!NewGameMilitary.Detached(w)?" / 主家兵糧：100人の約"+(v.Carry/(100d*3600)).ToString("0.00")+"時間分":"")+(w.NewMilitary?.Withdrawal!=null?" / "+NewGameMilitary.PersonalStatus(w):"");
    }
    void ExecuteMilitary(){var a=militaryActions[militaryChoice.Selected];if(a==NewMilitaryAction.Deploy){Span=90;nationMode=false;}if(a==NewMilitaryAction.CombatStart){Span=40;nationMode=false;}if(a==NewMilitaryAction.PersonalMove){drawingMilitary=drawingPersonal=true;message.Text="本人が歩く地点を地面で指定してください。部隊には命令しません。";return;}if(a==NewMilitaryAction.Form){drawingPersonal=false;drawingMilitary=true;message.Text="地面を押して離し、10m以上の配置線を指定してください。";return;}long amount=a==NewMilitaryAction.Load?Math.Min(100*86400L,NewGameMilitary.Capacity-NewGameMilitary.View(Snapshot()).Carry):a==NewMilitaryAction.Unload?NewGameMilitary.View(Snapshot()).Carry:0;Submit(Session.DecideNewMilitary(new NewMilitaryInput(new("request:new-military-ui/"+Session.Revision),a,amount){MotionContract=a==NewMilitaryAction.CombatStart?NewGameMilitary.RoutContract:null},Session.PlayerControl,Session.Revision));}
    internal void ChooseMilitary(NewMilitaryAction action){int i=Array.IndexOf(militaryActions,action);if(i<0)throw new InvalidDataException("軍務操作を選べません："+action+" / "+militaryStatus.Text);militaryChoice.Select(i);Press("military-execute");}
    void FormMilitary(FieldPoint a,FieldPoint b){Submit(Session.DecideNewMilitary(new(new("request:new-military-ui/"+Session.Revision),NewMilitaryAction.Form,0,a,b),Session.PlayerControl,Session.Revision));drawingMilitary=false;Refresh();}
    static bool MilitaryRay(Vector3 origin,Vector3 direction,Vector3 a,Vector3 b,Vector3 c,out Vector3 hit){hit=default;var e1=b-a;var e2=c-a;var h=direction.Cross(e2);double d=e1.Dot(h);if(Math.Abs(d)<1e-9)return false;var delta=origin-a;double u=delta.Dot(h)/d;if(u<-.00001||u>1.00001)return false;var q=delta.Cross(e1);double v=direction.Dot(q)/d;if(v<-.00001||u+v>1.00001)return false;double distance=e2.Dot(q)/d;if(distance<0)return false;hit=origin+direction*(float)distance;return true;}
    FieldPoint? MilitaryPick(Vector2 pixel){var origin=camera.ProjectRayOrigin(pixel);var dir=camera.ProjectRayNormal(pixel);Vector3? nearest=null;float best=float.MaxValue;foreach(var t in terrain.Picks){if(MilitaryRay(origin,dir,t.A+terrain.Position,t.B+terrain.Position,t.C+terrain.Position,out var p)&&origin.DistanceSquaredTo(p)<best){best=origin.DistanceSquaredTo(p);nearest=p;}}var center=FieldWorld.FromWorld(RenderPosition(Branch(Session.PlayerControl)));return nearest is {} at?new(center.X+(long)Math.Round(at.X*1000),center.Y-(long)Math.Round(at.Z*1000)):null;}
    void MilitarySurfaceInput(InputEvent e){if(!drawingMilitary||e is not InputEventMouseButton m||m.ButtonIndex!=MouseButton.Left)return;try{var p=MilitaryPick(m.Position*new Vector2(view.Size.X/surface.Size.X,view.Size.Y/surface.Size.Y));if(m.Pressed)militaryDrag=p;else if(militaryDrag is {} a&&p is {} b){militaryDrag=null;if(drawingPersonal){Submit(Session.DecideNewMilitary(new(new("request:personal-ui/"+Session.Revision),NewMilitaryAction.PersonalMove,0,b),Session.PlayerControl,Session.Revision));drawingMilitary=drawingPersonal=false;Refresh();}else FormMilitary(a,b);}}catch(Exception ex){message.Text="配置できません："+ex.Message;}}
    // Same viewport signal used by real ground input; no OS pointer/input calls.
    internal void ExercisePersonalMove(FieldPoint point)=>ExerciseMilitaryLine(point,point,true);
    internal void ExerciseMilitaryLine(FieldPoint a,FieldPoint b,bool personal=false){ChooseMilitary(personal?NewMilitaryAction.PersonalMove:NewMilitaryAction.Form);Vector2 Pixel(FieldPoint p){var center=FieldWorld.FromWorld(RenderPosition(Branch(Session.PlayerControl)));var v=new Vector3((p.X-center.X)/1000f,ContinuousWorld.Height(p)/1000f,-(p.Y-center.Y)/1000f);return camera.UnprojectPosition(v)*new Vector2(surface.Size.X/view.Size.X,surface.Size.Y/view.Size.Y);}using var down=new InputEventMouseButton{ButtonIndex=MouseButton.Left,Pressed=true,Position=Pixel(a)};using var up=new InputEventMouseButton{ButtonIndex=MouseButton.Left,Pressed=false,Position=Pixel(b)};surface.EmitSignal(Control.SignalName.GuiInput,down);surface.EmitSignal(Control.SignalName.GuiInput,up);if(drawingMilitary)throw new InvalidDataException("配置線が地形へ届きませんでした");}
    internal bool MilitaryModelsFit()=>militaryMarkers.All(m=>!camera.IsPositionBehind(m.Marker.Position)&&new Rect2(new Vector2(8,8),(Vector2)view.Size-new Vector2(16,16)).HasPoint(camera.UnprojectPosition(m.Marker.Position+Vector3.Up*5)));
    object? MilitaryPose(){var w=Snapshot();return w.NewMilitary==null?null:new{Routing=w.NewMilitary?.Rout,Personal=WithdrawalPose(w),Exercise=ExercisePose(w),Positions=Enumerable.Range(0,3).Select(i=>NewGameMilitary.Position(w,i,w.ElapsedSeconds)),Units=w.Units.Select(u=>new{u.Id,u.Commander,u.Soldiers,u.Organization}),Stock=w.ResourceLots.Select(l=>new{l.Id,l.Owner,l.Holder,l.Quantity}),SoldierModels=militaryModels.Select(m=>new{Position=V(m.Position),Rotation=V(m.Rotation),m.Visible}),Models=militaryMarkers.Select(m=>new{Position=V(m.Marker.Position),m.Marker.Visible,m.Label.Text})};}
    void RenderMilitary(ContractWorld w,FieldPoint center){if(militaryMarkers.Count==0&&w.NewMilitary!=null){surface.GuiInput+=MilitarySurfaceInput;for(int i=0;i<3;i++){var marker=new MeshInstance3D{Mesh=new CylinderMesh{TopRadius=.5f,BottomRadius=.7f,Height=.12f},MaterialOverride=new StandardMaterial3D{AlbedoColor=new Color("cbb774")}};stage.AddChild(marker);var label=WorldLabel("20/unit/"+i,16);militaryMarkers.Add((marker,label));if(i>0){var soldier=new Officer3DCustomActor{Scale=Vector3.One*2};stage.AddChild(soldier);soldier.Apply(Officer3DCustomActor.Preset("veteran"));militaryModels.Add(soldier);}}}
        RenderExercise(w,center);RenderWithdrawal(w,center);
        foreach(var actor in militaryModels)actor.Visible=false;
        for(int i=0;i<militaryMarkers.Count;i++){var pair=militaryMarkers[i];if(w.NewMilitary==null){pair.Marker.Visible=pair.Label.Visible=false;continue;}var current=NewGameMilitary.Position(w,i,w.ElapsedSeconds);var predicted=NewGameMilitary.Position(w,i,w.ElapsedSeconds+1);var p=new FieldPoint(current.X+(long)Math.Round((predicted.X-current.X)*fraction),current.Y+(long)Math.Round((predicted.Y-current.Y)*fraction));pair.Marker.Position=new((p.X-center.X)/1000f,ContinuousWorld.Height(p)/1000f+.1f,-(p.Y-center.Y)/1000f);pair.Marker.Visible=pair.Label.Visible=RegionalGround.Distance(p,center)<150000;PlaceWorldLabel(pair.Label,pair.Marker.Position+Vector3.Up*(i==0?2.5f:1.5f));if(i>0){var actor=militaryModels[i-1];actor.Position=pair.Marker.Position-Vector3.Up*.1f;actor.Visible=pair.Marker.Visible;var next=NewGameMilitary.Position(w,i,w.ElapsedSeconds+1);var heading=next!=p?new Vector2(next.X-p.X,-(next.Y-p.Y)):Vector2.Up;actor.Rotation=new(0,Mathf.Atan2(heading.X,heading.Y),0);bool fighting=ExerciseFighting(w,i);string animation=fighting?"attack":next!=p?"walk":"idle";if(fighting)actor.Rotation=new(0,Mathf.Pi/2,0);var clip=actor.Player.GetAnimation(actor.Clips[animation]);double distance=MilitaryDistance(w,i,w.ElapsedSeconds+fraction);actor.Freeze(animation,(next!=p?distance/1000d/(actor.WalkStride*actor.Scale.Z)*clip.Length:w.ElapsedSeconds+fraction)%clip.Length);}pair.Label.Text="主家"+(i==0?"本隊":i==1?"左分隊":"右分隊")+w.Units.Single(u=>u.Id==NewGameMilitary.UnitIds[i]).Soldiers+(w.NewMilitary.Rout==null?"":NewGameMilitary.RoutPhase(w,i) switch{"routed"=>"・敗走","rout-blocked"=>"・敗走経路待ち","regrouping"=>"・再集結待ち","regrouped"=>"・再集結済み",_=>""});}
    }
